static int cmf_copy_block ( struct ccw_device * cdev ) { struct subchannel * sch = to_subchannel ( cdev -> dev . parent ) ; struct cmb_data * cmb_data ; void * hw_block ; if ( scsw_fctl ( & sch -> schib . scsw ) & SCSW_FCTL_START_FUNC ) { if ( ( ! ( scsw_actl ( & sch -> schib . scsw ) & SCSW_ACTL_SUSPENDED ) ) && ( scsw_actl ( & sch -> schib . scsw ) & ( SCSW_ACTL_DEVACT | SCSW_ACTL_SCHACT ) ) && ( ! ( scsw_stctl ( & sch -> schib . scsw ) & SCSW_STCTL_SEC_STATUS ) ) ) { return - EBUSY ; } } cmb_data = cdev -> private -> cmb ; hw_block = cmb_data -> hw_block ; memcpy ( cmb_data -> last_block , hw_block , cmb_data -> size ) ; cmb_data -> last_update = get_tod_clock ( ) ; return 0 ; } 